 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="local_connector_device_id")private BrowserDevice device;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="boss_account_id")private BossAccount account;@Column(name="chat_digest",nullable=false,length=64)private String chatDigest;@Column(name="preview_digest",length=64)private String previewDigest;@Column(name="job_digest",length=64)private String jobDigest;@Column(name="observed_job_title",length=120)private String observedJobTitle;@Column(name="time_digest",length=64)private String timeDigest;@Column(name="unread_count",nullable=false)private int unreadCount;@Column(nullable=false)private boolean unread;@Column(name="draft_mode",length=24)private String draftMode;@Column(name="draft_content",columnDefinition="TEXT")private String draftContent;@Column(name="draft_reason",length=200)private String draftReason;@Column(name="draft_generated_at")private Instant draftGeneratedAt;@Column(name="draft_qualification",length=32)private String draftQualification;@Column(name="matched_job_position_id")private UUID matchedJobPositionId;@Column(name="manual_match_job_position_id")private UUID manualMatchJobPositionId;@Column(name="manual_match_title_key",length=160)private String manualMatchTitleKey;@Column(name="manual_matched_at")private Instant manualMatchedAt;@Column(name="draft_blocker_codes",length=500)private String draftBlockerCodes;@Column(name="draft_company_knowledge_version")private Integer draftCompanyKnowledgeVersion;@Column(name="draft_job_knowledge_version")private Integer draftJobKnowledgeVersion;@Column(name="eligibility_status",nullable=false,length=32)private String eligibilityStatus="OBSERVING";@Column(name="latest_message_digest",length=64)private String latestMessageDigest;@Column(name="latest_direction",length=16)private String latestDirection;@Column(name="latest_message_at")private Instant latestMessageAt;@Column(name="detail_verified_at")private Instant detailVerifiedAt;@Column(name="review_status",nullable=false,length=24)private String reviewStatus="PENDING";@Column(name="reviewed_content",columnDefinition="TEXT")private String reviewedContent;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reviewed_by")private SystemUser reviewedBy;@Column(name="reviewed_at")private Instant reviewedAt;@Column(name="review_note",length=300)private String reviewNote;@Column(name="draft_fill_status",nullable=false,length=16)private String draftFillStatus="NONE";@Column(name="draft_fill_token_hash",length=64)private String draftFillTokenHash;@Column(name="draft_fill_expires_at")private Instant draftFillExpiresAt;@Column(name="draft_fill_digest",length=64)private String draftFillDigest;@Column(name="draft_filled_at")private Instant draftFilledAt;@Column(name="draft_fill_device_id")private UUID draftFillDeviceId;@Column(name="resolution_status",nullable=false,length=32)private String resolutionStatus="UNRESOLVED";@Column(name="resolved_at")private Instant resolvedAt;@Column(name="first_seen_at",nullable=false)private Instant firstSeenAt;@Column(name="last_seen_at",nullable=false)private Instant lastSeenAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;
